import * as React from "react";
import { VideoTutorialCard } from "../VideoTutorialCard";

export function VideoTutorialExample() {
  return <VideoTutorialCard />;
}

export { VideoTutorialCard } from "./VideoTutorialCard";
export { VideoTutorialExample } from "./examples/VideoTutorialExample";
export { VideoTutorialCompactExample } from "./examples/VideoTutorialCompactExample";
export * from "./types";
export * from "./constants";

export type VideoTutorialBlockPropsType = {
  title?: string;
  description?: string;
